/**
 * Names and paths shared by the storefront session server (BFF) and the browser. The token
 * cookies are HttpOnly and never readable here; the browser sees only the two flags below.
 */

/** Base path of the session route handlers generated by the storefront runtime. */
export const AUTH_BASE_PATH = '/auth';

/** Header every browser call to the session handlers sends; it forces a CORS preflight. */
export const SESSION_REQUEST_HEADER = 'x-shopana-session';

/** Readable flag that a session exists, so an anonymous page does not ask the server. */
export const SIGNED_IN_COOKIE = 'shopana_signed_in';

/** Readable one-shot flag set by `/auth/callback`: the next page load completes the sign-in. */
export const AUTH_EVENT_COOKIE = 'shopana_auth_event';

/** Query parameter `/auth/callback` adds to `returnTo` when the sign-in did not complete. */
export const AUTH_RESULT_PARAM = 'auth';

export type AuthResult = 'cancelled' | 'failed';

export function readBrowserCookie(name: string): string | null {
  if (typeof document === 'undefined') return null;
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = document.cookie.match(new RegExp(`(?:^|; )${escaped}=([^;]*)`));
  return match ? decodeURIComponent(match[1]) : null;
}

export function removeBrowserCookie(name: string): void {
  if (typeof document === 'undefined') return;
  document.cookie = `${name}=; Path=/; Max-Age=0; SameSite=Lax`;
}
